from pycompss.api.task import task
from pycompss.api.api import compss_wait_on


@task(returns=1)
def compute_jacobi_row(row_elements, diag_val, b_val, x_old):
    sum_Ax = 0.0
    for col, val in row_elements:
        sum_Ax += val * x_old[col]

    return (b_val - sum_Ax) / diag_val

def main(A_coo, b, max_iterations=50, tolerance=1e-5):
    N = len(b)

    A_rows = [[] for _ in range(N)]
    A_diagonals = [0.0] * N

    for elem in A_coo:
        r = elem['row']
        c = elem['column']
        v = elem['value']

        if r == c:
            A_diagonals[r] = v
        else:
            A_rows[r].append((c, v))

    x = [0.0] * N 

    for iteration in range(1, max_iterations + 1):
        x_new_futures = []

        for i in range(N):
            future_x_i = compute_jacobi_row(A_rows[i], A_diagonals[i], b[i], x)
            x_new_futures.append(future_x_i)

        x_new = compss_wait_on(x_new_futures)

        current_error = max(abs(x_new[i] - x[i]) for i in range(N))

        if current_error < tolerance:
            print(f"      [!] Converged early at iteration {iteration} (Delta: {current_error:.2e})")
            break

        x = x_new

    return x
